async function openWardrobe(origin='room'){
 const fromProfile=origin==='profile';if(!user){login(()=>openWardrobe('profile'));return;}
 if(!wardrobeAccess(fromProfile?'profile':'room',state,canPlay()))return toast('El vestuario está disponible antes de empezar.');
 wardrobeGuard=syncWardrobeToRoom(state,canPlay())?state.matchId:null;
 const back=()=>{wardrobeGuard=null;if(fromProfile||!state||!role)return profile();renderRoom();};
 setView('wardrobe');navRender();root.append(el('p','sub','Preparando tu personaje…'));
 try{const {user:u,progression}=await api('/api/me');if(view!=='wardrobe')return;if(shouldCloseWardrobe(wardrobeGuard,state)){renderRoom();return;}
 user=u;let legacy=null;try{legacy=localStorage.getItem('mq.personality.'+u.id);}catch{}const wardrobeUser={...u,avatar:{...u.avatar,personality:u.avatar?.personality??(legacy==='balanced'?'random':legacy||'random')}};wardrobe({user:wardrobeUser,progression,backLabel:fromProfile||!state?'Volver a mi perfil':'Volver al concurso',accountOnly:fromProfile&&!syncWardrobeToRoom(state,canPlay()),save:async data=>{
 if(view!=='wardrobe')throw Error('El editor ya no está abierto.');
 if(!fromProfile&&shouldCloseWardrobe(wardrobeGuard,state))throw Error('El concurso ya ha empezado.');
 const result=await api('/api/profile',data);user=result.user;try{localStorage.removeItem('mq.personality.'+user.id);}catch{}navRender();
 if(syncWardrobeToRoom(state,canPlay())){try{await send('join',{code:state.code,role});}catch(e){toast('Personaje guardado en tu cuenta. La sala no se ha actualizado.');if(view==='wardrobe')await back();return;}}
 if(view==='wardrobe')await back();toast('¡Personaje guardado!');
 },close:back});
 }catch(e){toast(e.message);if(view==='wardrobe')await back();}
}

function renderArcade(parent,q,revealed){if(!['memory','odd','reflex','count','number-hunt'].includes(q.party))return false;const me=state.players.find(p=>p.id===playerId);if(['memory','count'].includes(q.party)){if(state.partyStage==='memory-show'&&!revealed){parent.append(el('p','sub','¡Memoriza!'),put(el('div',q.party==='count'?'count-board':'memory-strip'),...(q.preview||[]).map(s=>el('span','memory-symbol',s))));return true;}return false;}if(q.party==='number-hunt'){if(revealed){parent.append(el('p','feedback','¡Fin de la escalera!'));return true;}const chosen=[];const grid=el('div','odd-grid number-hunt');for(const [i,v] of q.options.entries()){const b=button(v,'odd-tile',()=>{if(chosen.includes(i))return;chosen.push(i);b.disabled=true;b.classList.add('cleared');if(chosen.length===q.options.length)submitAnswer(chosen);});b.disabled=!canPlay()||!!me?.answered;grid.append(b);}parent.append(grid,el('p','sub','Pulsa todos los números de menor a mayor.'));return true;}if(revealed){parent.append(el('div','result',q.party==='reflex'?'¡Fin de la carrera de reflejos!':'¡Este era el símbolo diferente!'));if(q.party==='odd')parent.append(el('div','memory-symbol',q.options[q.correct]));return true;}if(me?.answered){parent.append(el('p','feedback','¡Intento registrado!'));return true;}if(q.party==='reflex'){const go=state.partyStage==='reflex-go';const b=button(go?'¡YA!':'ESPERA…','reflex-pad '+(go?'go':'wait'),()=>{b.disabled=true;navigator.vibrate?.(30);submitAnswer(0);});b.disabled=!canPlay();parent.append(b,el('p','sub','Pulsar antes de la señal cuenta como intento fallido.'));return true;}const grid=el('div','odd-grid');for(const [i,v] of q.options.entries()){const b=button(v,'odd-tile',()=>{b.classList.add('pad-fired');submitAnswer(i);});b.disabled=!canPlay();grid.append(b);}parent.append(grid);return true;}

function renderDrawing(parent,q,revealed){const isDrawer=canPlay()&&playerId===state.drawer&&!revealed,drawer=state.players.find(p=>p.id===state.drawer);const board=createDrawBoard({drawer:isDrawer,questionId:q.id,send,secret:()=>send('draw-secret',{questionId:q.id})});board.id='live-drawing';board.update(state.strokes||[]);parent.append(el('p','sub',(drawer?.name||'Un concursante')+' está dibujando'),board);if(revealed){parent.append(el('div','result','La palabra era: '+q.correct));return;}if(isDrawer){parent.append(el('p','sub','No escribas letras ni números. ¡Que tus amigos lo adivinen!'));return;}if(!canPlay())return;const input=el('input');input.id='drawing-guess';input.maxLength=64;input.placeholder='¿Qué está dibujando?';const status=el('p','sub');status.id='drawing-status';const b=button('Adivinar','primary full',async()=>{if(!input.value.trim()||b.disabled||input.disabled)return;b.disabled=true;try{const r=await send('draw-guess',{questionId:q.id,text:input.value});if(r.correct){status.textContent='¡Lo has adivinado!';input.disabled=true;}else{status.textContent='¡Sigue intentándolo!';input.value='';input.focus();}}catch(e){status.textContent=e.message;}finally{b.disabled=false;}});input.onkeydown=e=>{if(e.key==='Enter')b.click();};parent.append(input,b,status);}

