// A read-only television has no scroll controls. Fit long questions, media and options into the available panel.
function fitTvQuestion(panel,content){let frame,observer,mutations;const fit=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{if(!panel.isConnected)return;content.style.transform='none';const available=panel.clientHeight-parseFloat(getComputedStyle(panel).paddingTop)-parseFloat(getComputedStyle(panel).paddingBottom),height=content.scrollHeight;if(available>0&&height>available+2){const scale=Math.max(.25,available/height);content.style.transform='scale('+scale+')';}});};fit();if(window.ResizeObserver){observer=new ResizeObserver(fit);observer.observe(panel);observer.observe(content);}if(window.MutationObserver){mutations=new MutationObserver(fit);mutations.observe(content,{childList:true,subtree:true,characterData:true});}const detach=new MutationObserver(()=>{if(!panel.isConnected){observer?.disconnect();mutations?.disconnect();detach.disconnect();cancelAnimationFrame(frame);}});detach.observe(root,{childList:true,subtree:true});content.querySelectorAll('img,video').forEach(m=>{m.addEventListener('load',fit);m.addEventListener('loadedmetadata',fit);});document.fonts?.ready.then(fit);}

function makeDifficultyPicker(){const node=el('section','mode-setting difficulty-picker'),header=el('div','difficulty-heading'),value=el('strong','difficulty-value'),hint=el('p','difficulty-hint'),rail=el('div','difficulty-rail'),choices=el('div','difficulty-choices'),range=el('input','difficulty-range'),mix=button('🎲  Mezclar niveles','difficulty-mix',()=>choose('Mixta'));let selected='Media';header.append(el('span','setup-section-label','02 / DIFICULTAD'),value);range.type='range';range.min=0;range.max=4;range.step=1;range.value=2;range.setAttribute('aria-label','Dificultad de muy fácil a muy difícil');rail.append(range);const buttons=levels.map((l,i)=>{const b=button('','difficulty-stop',()=>choose(l.id));b.style.setProperty('--level-color',l.color);b.append(el('span','difficulty-icon',l.icon),el('b','',l.label));choices.append(b);return b;});function choose(id){selected=id;const i=levels.findIndex(l=>l.id===id),l=levels[i];if(l)range.value=String(i);range.setAttribute('aria-valuetext',l?.label||'Mixta');node.style.setProperty('--level-color',l?.color||'#c5a9ff');value.textContent=l?l.icon+' '+l.label:'🎲 Mixta';hint.textContent=l?.hint||'Una combinación de preguntas de todos los niveles.';buttons.forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));mix.setAttribute('aria-pressed',String(i<0));rail.classList.toggle('mixed',i<0);}range.oninput=()=>choose(levels[Number(range.value)].id);node.append(header,rail,choices,hint,mix);choose('Media');return {node,get value(){return selected;}};}
