// iOS rubber-banding fallback; scoped to active Arcade only, never the whole site.
document.addEventListener('touchmove',e=>{if(document.body.classList.contains('arcade-viewport')&&blockArcadePan(e,root))e.preventDefault();},{passive:false});
function updateConnectionUI(){const status=socket?.status;let banner=$('#connection-indicator');if(!state||!role||status==='connected'||!status){banner?.remove();return;}if(!banner){banner=el('div','connection-indicator');banner.id='connection-indicator';banner.setAttribute('role','status');document.body.append(banner);}banner.textContent=status==='expired'?'La sala ha caducado. Vuelve al inicio.':status==='connecting'?'Conectando al plató…':'Reconectando al plató… No cierres el juego.';banner.dataset.status=status;banner.classList.toggle('connection-compact',(['wardrobe','profile'].includes(view)||document.body.classList.contains('arcade-viewport')||document.body.classList.contains('order-controller')||document.body.classList.contains('quiz-controller'))&&status!=='expired');}
window.addEventListener('online',()=>{if(socket&&!socket.closed){clearTimeout(socket.timer);socket.open();}});window.addEventListener('offline',()=>socket?.setStatus('reconnecting'));

function showUnlockCelebration(achievements,level){document.querySelector('.unlock-celebration')?.remove();const banner=el('aside','unlock-celebration');banner.setAttribute('role','status');banner.append(el('span','unlock-medal','★'),el('strong','',level?'¡NIVEL '+level+'!':'¡LOGRO DESBLOQUEADO!'));for(const a of achievements.slice(0,3))banner.append(el('b','',a.name),el('small','','Recompensa: '+a.label));if(achievements.length>3)banner.append(el('small','','+'+(achievements.length-3)+' logros más en tu perfil'));banner.append(button('Cerrar','ghost',()=>banner.remove()));document.body.append(banner);playSound('rank');confetti(banner);setTimeout(()=>banner.remove(),8500);}

function resultCaption(q){if(!q||isAction(q.party)||['reflex','odd','memory','count','number-hunt'].includes(q.party))return '¡Prueba terminada!';if(q.party==='draw')return 'La palabra era: '+q.correct;if(q.party==='bluff')return 'La respuesta era: '+q.correct;if(q.party==='estimate')return 'La cifra real: '+Number(q.correct).toLocaleString('es-ES',{maximumFractionDigits:6});try{const label=answerLabel(q);return label===undefined||label===null||label==='undefined'?'¡Ronda terminada!':'Respuesta: '+label;}catch{return '¡Ronda terminada!';}}

function roundRule(party){return ({tiebreak:{title:'MUERTE SÚBITA',hint:'Solo responden los líderes empatados.'},warmup:{title:'PREGUNTAS CLÁSICAS',hint:'Cuatro opciones. Acierta cuanto antes.'},'order-round':{title:'PONLO EN ORDEN',hint:'Ordena los elementos y confirma antes de que acabe el tiempo.'},estimate:{title:'LA CIFRA JUSTA',hint:state?.solo?'Acércate lo máximo posible a la cifra real.':'La cifra más cercana gana 1.000 puntos.'},buzzer:{title:'EL GRAN PULSADOR',hint:'Pulsa si sabes la respuesta. Fallo o tiempo agotado: hasta −'+BUZZER_PENALTY+' puntos. Si no pulsas, no pierdes nada.'},steal:{title:'ROBAPUNTOS',hint:'El acierto más rápido roba hasta 400 puntos al rival mejor situado (máximo 20 %).'},final:{title:'GRAN FINAL · ×'+(state?.question?.multiplier||2),hint:state?.question?.multiplier===3?'Última oportunidad: ¡cada acierto vale el triple!':'¡Todos los aciertos valen el doble!'},'solo-bonus':{title:'BONUS INDIVIDUAL · ×1,5',hint:'Acierta y consigue un 50 % más de puntos.'},wager:{title:'LA GRAN SUBASTA',hint:'Arriesga parte de tus puntos antes de ver la pregunta.'},bluff:{title:'EL FARSANTE',hint:'Inventa una mentira y encuentra la respuesta verdadera.'},hot:{title:'PATATA CALIENTE',hint:'Responde bien y pasa el turno.'},pie:{title:'TARTAZO',hint:'Acierta para lanzar una tarta a un rival.'}})[party];}

function roundJourney(s){const wrap=el('div','round-journey'),track=el('div','round-journey-track'),label=el('div','journey-label');wrap.setAttribute('aria-label','Recorrido del Gran Concurso');const descriptors={warmup:['●','Preguntas clásicas','#79c9ff'],'order-round':['↕','Orden','#c9b6ff'],estimate:['≈','Cifra justa','#77e2b2'],buzzer:['⚡','Pulsador','#ffd55a'],wager:['±','Subasta','#ffbf82'],bluff:['?','Farsante','#d3a3ff'],hot:['!','Patata','#ffa971'],pie:['✦','Tartazo','#ffb1ba'],draw:['✎','Dibujo','#9ed8ff'],steal:['↔','Robapuntos','#ff829d'],final:['×3','Gran final','#ffd55a'],tiebreak:['⚡','Desempate','#ffd55a'],'solo-bonus':['×1,5','Bonus','#ff829d'],custom:['★','Amigos','#aeeed1']};const groups=[];for(const [i,party] of (s.playlist||[]).entries()){const last=groups[groups.length-1];if(last?.party===party)last.end=i;else groups.push({party,start:i,end:i});}if(!groups.length)return wrap;const current=groups.findIndex(g=>s.index>=g.start&&s.index<=g.end);label.textContent=current<0?'EL RECORRIDO DEL CONCURSO':'BLOQUE '+(current+1)+' / '+groups.length;for(const [i,g] of groups.entries()){const [symbol,name,color]=descriptors[g.party]||['•','Ronda','#d7c7e9'],step=el('div','journey-stop');step.style.setProperty('--journey-color',color);step.dataset.status=current===i?'current':current>i?'done':'next';step.append(el('b','journey-symbol',current>i?'✓':symbol),el('span','journey-name',name),el('small','journey-count',String(g.end-g.start+1)));step.setAttribute('aria-label',name+', '+(g.end-g.start+1)+' preguntas'+(current===i?', bloque actual':''));if(current===i)step.setAttribute('aria-current','step');track.append(step);}wrap.append(label,track);return wrap;}

function syncSocialUI(){
 const active=!!state&&view===role&&!!role,allowed=active&&role!=='screen'&&state.sharedDisplay&&!state.solo&&state.players.some(p=>p.id===playerId);
 let trigger=$('#social-trigger');const dialog=$('#social-picker');
 if(!allowed){trigger?.remove();if(dialog?.open)dialog.close();}else if(!trigger){trigger=button('😊 Reaccionar','social-trigger',openSocialPicker);trigger.id='social-trigger';(root.querySelector('.room-head')||root).append(trigger);}
 const now=Date.now()+offset,event=active&&role==='screen'?liveReaction(state.socialReaction,now):null;let mini=$('#social-mini');
 if(!event){mini?.remove();return;}
 const bubble=$('#tv-stage .stage-social-bubble');
 if(event.kind!=='tomato'&&bubble?.dataset.event===event.id&&!bubble.hidden){mini?.remove();return;}
 if(event.kind!=='tomato'&&now-event.at<350&&$('#tv-stage.stage-ready'))return;
 if(mini?.dataset.event===event.id)return;
 mini?.remove();const from=state.players.find(p=>p.id===event.from),target=state.players.find(p=>p.id===event.target);if(!from)return;
 mini=el('aside','social-mini');mini.id='social-mini';mini.dataset.event=event.id;mini.dataset.kind=event.kind;mini.style.setProperty('--social-delay',-(now-event.at)/1000+'s');mini.append(el('div','social-mini-label','● MINICÁMARA · EN DIRECTO'));
 const cast=el('div','social-mini-cast'),person=(p,action)=>{const card=el('div','social-mini-person');card.append(fullAvatarNode(p.avatar,p.name,action),el('b','',p.name));return card;};
 cast.append(person(from,event.kind==='tomato'?'throw':event.kind==='shock'?'shrug':event.kind==='laugh'?'dance':'celebrate'));
 if(event.kind==='tomato'&&target)cast.append(person(target,'hit'),el('span','social-flying-tomato','🍅'),el('span','social-splat','💥'));else cast.append(el('span','social-mini-emoji',reactions[event.kind]));
 mini.append(cast,el('div','social-mini-caption',target?from.name+' → '+target.name:from.name+' '+reactions[event.kind]));root.append(mini);
}
function openSocialPicker(){
 if(!state?.sharedDisplay||!playerId)return;$('#social-picker')?.remove();const d=el('dialog','social-picker');d.id='social-picker';d.append(el('h3','','Reacciona al plató'));const body=el('div','social-picker-body');d.append(body,button('Cerrar','ghost full',()=>d.close()));const matchId=state.matchId;
 const emit=async(kind,target)=>{try{await send('social-reaction',{kind,target,matchId});if(d.open)d.close();}catch(e){toast(e.message);}};
 const options=()=>{body.replaceChildren();const grid=el('div','social-emoji-grid');for(const [kind,emoji] of Object.entries(reactions)){const b=button(emoji,'social-emoji',()=>{if(kind==='tomato')targets();else emit(kind);});b.setAttribute('aria-label',({laugh:'Risa',shock:'Sorpresa',clap:'Aplausos',fire:'Épico',tomato:'Lanzar tomate'})[kind]);b.disabled=kind==='tomato'&&(!tomatoAllowed(state)||state.players.length<2);grid.append(b);}body.append(grid,el('p','footnote','Los tomates se lanzan entre preguntas. No afectan a los puntos.'));};
 const targets=()=>{body.replaceChildren(el('p','','¿A quién le lanzas el tomate?'));const grid=el('div','social-target-grid');for(const p of state.players.filter(p=>p.id!==playerId)){const b=button('','social-target',()=>emit('tomato',p.id));b.append(avatarNode(p.avatar,p.name),el('b','',p.name));grid.append(b);}body.append(grid,button('← Volver','ghost',options));};
 options();document.body.append(d);d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();
}

function compactMedia(){return matchMedia('(max-width:800px), (max-height:520px) and (pointer:coarse)').matches;}
function mountCompactQuiz(main,top){
 const answers=main.querySelector('#answers');if(!answers)return;
 const prompt=el('div','quiz-prompt');
 for(const child of [...main.children]){if(child===answers)break;if(child.id==='timebar'||child.classList.contains('timer'))continue;prompt.append(child);}
 main.insertBefore(prompt,answers);prompt.tabIndex=0;prompt.setAttribute('aria-label','Enunciado y pistas');
 document.body.classList.add('quiz-controller');
 const more=button('⋯','quiz-more',()=>openQuizMenu());more.setAttribute('aria-label','Opciones del concurso');top.append(more);
 window.scrollTo(0,0);fitCompactQuiz(main);
}
function openQuizMenu(){
 if(!state||!role)return;const d=el('dialog','quiz-menu');d.append(el('h3','','Opciones del concurso'));
 if(role==='host'&&!state.solo)d.append(button('Jugar en TV','secondary full',()=>{d.close();tvMenu();}),button('Compartir TV','ghost full',()=>{d.close();share(screenLink(),'Pantalla MobiQuiz');}));
 d.append(button('Clasificación','secondary full',()=>{d.close();openQuickRanking();}),button('Salir del concurso','ghost full',()=>{if(confirm('¿Quieres salir del concurso?')){d.close();home();}}),button('Seguir jugando','primary full',()=>d.close()));document.body.append(d);d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();
}

function syncQuizViewport(){if(!window.visualViewport)return;document.body.style.setProperty('--quiz-height',Math.round(window.visualViewport.height)+'px');}
window.visualViewport?.addEventListener('resize',syncQuizViewport);syncQuizViewport();

function openQuestionImage(source){if(!source.naturalWidth||!source.isConnected)return;const previous=$('#question-image-viewer');if(previous){previous.close();previous.remove();}const d=el('dialog','question-image-viewer'),head=el('div','question-image-viewer-head'),image=el('img');d.id='question-image-viewer';d.setAttribute('aria-label','Imagen completa de la pregunta');head.append(el('strong','','Imagen completa'),button('Cerrar ✕','secondary',()=>d.close()));image.src=source.currentSrc||source.src;image.alt='Imagen de la pregunta ampliada';d.append(head,image,el('p','sub','El tiempo de la ronda sigue corriendo.'));document.body.append(d);d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();}

async function editLobbyQuestions(){
 if(role!=='host'||state?.phase!=='lobby'||$('#lobby-question-editor'))return;
 const match=state.matchId,code=state.code;
 try{const {selection:current}=await send('question-settings');if(state?.matchId!==match||state.phase!=='lobby')return;
 const selected=await Promise.all(current.packIds.map(async id=>{try{return (await api('/api/packs/lookup',{id})).pack;}catch{return {id,title:'Pack no disponible ('+id.slice(0,6)+')'};}}));
 if(state?.matchId!==match||state.phase!=='lobby')return;
 const selection={standard:current.standard,categories:current.categories===null?null:[...current.categories],packs:new Map(selected.map(p=>[p.id,p]))};
 await openLibrary({api,notify:toast,user,selection,editorMatch:match,onApply:async value=>{if(role!=='host'||state?.code!==code||state.matchId!==match||state.phase!=='lobby')throw Error('La partida ya ha empezado.');await send('question-settings',{selection:value});toast('Preguntas actualizadas para toda la sala.');}});
 }catch(e){toast(e.message);}
}

function fitCompactQuiz(main){const prompt=main.querySelector('.quiz-prompt'),answers=main.querySelector('#answers');if(!prompt||!answers)return;const fit=()=>{if(!main.isConnected)return;for(const section of [prompt,answers]){section.style.setProperty('--fit-font','1');section.style.zoom='1';const limit=section.clientHeight;if(limit>0&&section.scrollHeight>limit+2){let ratio=Math.max(.5,Math.min(1,limit/section.scrollHeight));section.style.setProperty('--fit-font',String(ratio));section.style.zoom=String(ratio);}}};let frame=0;const queue=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(fit);};const ro=new ResizeObserver(queue);ro.observe(main);const mo=new MutationObserver(queue);mo.observe(answers,{childList:true,subtree:true});const detach=new MutationObserver(()=>{if(!main.isConnected){ro.disconnect();mo.disconnect();detach.disconnect();cancelAnimationFrame(frame);}});detach.observe(root,{childList:true});queue();}
